@st.cache_resource(show_spinner=False)
def prepare_frontend():
    # Each server creates its own directory. No asset uploads or network fetches.
    folder = Path(tempfile.mkdtemp(prefix="flowery_frontend_"))
    content = gzip.decompress(base64.b64decode(GAME_DATA)).decode("utf-8")
    (folder / "index.html").write_text(content, encoding="utf-8")
    return str(folder)

flowery = components.declare_component("flowery_battle", path=prepare_frontend())
flowery(key="flowery_game", default=None)
